from functools import wraps


def retry(max_attempts, exceptions=(Exception,)):
    if max_attempts <= 0:
        raise ValueError("max_attempts must be greater than 0")

    # Normalize exceptions to a tuple
    if isinstance(exceptions, type) and issubclass(exceptions, BaseException):
        exceptions = (exceptions,)
    elif isinstance(exceptions, tuple):
        pass
    else:
        # If it's a list or other iterable, convert to tuple
        exceptions = tuple(exceptions)

    def decorate(fn):
        @wraps(fn)
        def wrapped(*args, **kwargs):
            attempts = 0
            last_exception = None
            while attempts < max_attempts:
                attempts += 1
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
                    if attempts >= max_attempts:
                        raise
            # If we exit the loop without returning or raising, re-raise the last exception
            if last_exception is not None:
                raise last_exception
            return None
        return wrapped
    return decorate
