#include <cstdint>

int main() {
    int n;
    std::cin >> n;

    std::vector<std::pair<int64_t, int64_t>> ranges;
    ranges.reserve(n);

    for (int i = 0; i < n; ++i) {
        int64_t l, r;
        std::cin >> l >> r;
        if (l > r) {
            std::cout << "INVALID\n";
            return 0;
        }
        ranges.emplace_back(l, r);
    }

    // Sort by start, then by end
    std::sort(ranges.begin(), ranges.end(), [](const auto& a, const auto& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    // Merge overlapping or adjacent ranges
    std::vector<std::pair<int64_t, int64_t>> merged;
    if (!ranges.empty()) {
        int64_t cur_l = ranges[0].first;
        int64_t cur_r = ranges[0].second;

        for (size_t i = 1; i < ranges.size(); ++i) {
            int64_t l = ranges[i].first;
            int64_t r = ranges[i].second;

            // Check if [l, r] overlaps or is adjacent to [cur_l, cur_r]
            // Adjacent means l == cur_r + 1, but we must avoid overflow.
            // Instead, check: l <= cur_r + 1  <=>  l - 1 <= cur_r
            // But l - 1 can underflow if l == INT64_MIN.
            // Better: check if l <= cur_r + 1 without computing cur_r + 1.
            // We can check: l <= cur_r + 1  is equivalent to:
            //   if cur_r == INT64_MAX, then any l <= INT64_MAX is true (since l is int64_t)
            //   otherwise, l <= cur_r + 1
            // Alternatively: l <= cur_r + 1  <=>  l - 1 <= cur_r, but l-1 underflows at INT64_MIN.
            // Safest: check if l <= cur_r + 1 by checking:
            //   cur_r == INT64_MAX ? true : l <= cur_r + 1
            // But cur_r + 1 overflows at INT64_MAX. So:
            bool adjacent_or_overlap;
            if (cur_r == INT64_MAX) {
                // cur_r + 1 would overflow, but any l (which is <= INT64_MAX) satisfies l <= cur_r + 1
                adjacent_or_overlap = true;
            } else {
                // cur_r + 1 is safe
                adjacent_or_overlap = (l <= cur_r + 1);
            }

            if (adjacent_or_overlap) {
                // Merge: extend cur_r to max(cur_r, r)
                if (r > cur_r) {
                    cur_r = r;
                }
            } else {
                // No overlap/adjacency, push current merged range
                merged.emplace_back(cur_l, cur_r);
                cur_l = l;
                cur_r = r;
            }
        }
        // Push the last merged range
        merged.emplace_back(cur_l, cur_r);
    }

    std::cout << merged.size() << "\n";
    for (const auto& p : merged) {
        std::cout << p.first << " " << p.second << "\n";
    }

    return 0;
}
