    if (!(cin >> n >> k)) return 0;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    if (k <= 0 || k > n) {
        cout << "INVALID\n";
        return 0;
    }

    // Use 64-bit for sum
    int64_t sum = 0;
    for (int i = 0; i < k; ++i) sum += a[i];

    // Monotonic deques for min and max
    deque<int> minDeque, maxDeque;

    // Initialize deques for the first window [0, k-1]
    for (int i = 0; i < k; ++i) {
        while (!minDeque.empty() && a[minDeque.back()] >= a[i]) {
            minDeque.pop_back();
        }
        minDeque.push_back(i);

        while (!maxDeque.empty() && a[maxDeque.back()] <= a[i]) {
            maxDeque.pop_back();
        }
        maxDeque.push_back(i);
    }

    // Iterate over all windows
    for (int left = 0; left + k <= n; ++left) {
        // Remove elements that are out of the current window
        while (!minDeque.empty() && minDeque.front() < left) {
            minDeque.pop_front();
        }
        while (!maxDeque.empty() && maxDeque.front() < left) {
            maxDeque.pop_front();
        }

        int mn = a[minDeque.front()];
        int mx = a[maxDeque.front()];

        cout << sum << ' ' << mn << ' ' << mx << '\n';

        // Update sum for next window
        if (left + k < n) {
            sum -= a[left];
            sum += a[left + k];

            // Add new element to deques
            int newIdx = left + k;
            while (!minDeque.empty() && a[minDeque.back()] >= a[newIdx]) {
                minDeque.pop_back();
            }
            minDeque.push_back(newIdx);

            while (!maxDeque.empty() && a[maxDeque.back()] <= a[newIdx]) {
                maxDeque.pop_back();
            }
            maxDeque.push_back(newIdx);
        }
    }

    return 0;
}
