    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<long long> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    SegmentTree st(n);
    st.build(arr, 1, 0, n - 1);

    while (q--) {
        string op;
        cin >> op;
        if (op == "ADD") {
            int l, r;
            long long x;
            cin >> l >> r >> x;
            x = (x % MOD + MOD) % MOD;
