def resolve_order(graph):
    # Build the set of all nodes
    all_nodes = set()
    for node, deps in graph.items():
        all_nodes.add(node)
        for dep in deps:
            all_nodes.add(dep)

    # Build adjacency: for each node, its dependencies (edges dep -> node)
    # We need to track in-degree: number of dependencies not yet emitted
    # Actually, let's think: a node is eligible when all its dependencies have been emitted.
    # So for each node, we need to know how many of its dependencies have been emitted.

    # Let's build a map: node -> set of dependencies (deduplicated)
    node_deps = {}
    for node, deps in graph.items():
        node_deps[node] = set(deps)

    # For nodes that appear only in dependency lists but not as keys in graph,
    # they have no dependencies of their own (empty set)
    for node in all_nodes:
        if node not in node_deps:
            node_deps[node] = set()

    # Now, we need to track for each node, how many of its dependencies have been emitted.
    # Alternatively, we can track the number of unmet dependencies.

    # Let's use a different approach:
    # For each node, count how many dependencies it has.
    # As we emit nodes, we decrement the count for nodes that depend on the emitted node.

    # Build reverse adjacency: for each dependency, which nodes depend on it
    dependents = {node: set() for node in all_nodes}
    for node, deps in node_deps.items():
        for dep in deps:
            dependents[dep].add(node)

    # Initialize remaining dependency count for each node
    remaining = {}
    for node in all_nodes:
        remaining[node] = len(node_deps[node])

    # Use a min-heap (priority queue) for lexicographically smallest eligible node
    import heapq

    # Initialize heap with all nodes that have 0 remaining dependencies
    heap = []
    for node in all_nodes:
        if remaining[node] == 0:
            heapq.heappush(heap, node)

    result = []
    emitted = set()

    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        emitted.add(node)

        # For each node that depends on this node, decrement their remaining count
        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in graph")

    return result
