using namespace std;

const long long MOD = 1000000007LL;

struct SegmentTree {
    int n;
    vector<long long> tree;
    vector<long long> lazy_mul;
    vector<long long> lazy_add;

    SegmentTree(int _n) : n(_n) {
        tree.assign(4 * n, 0);
        lazy_mul.assign(4 * n, 1);
        lazy_add.assign(4 * n, 0);
    }

    void build(const vector<long long>& arr, int node, int l, int r) {
        if (l == r) {
            tree[node] = arr[l] % MOD;
            if (tree[node] < 0) tree[node] += MOD;
            return;
        }
        int mid = (l + r) / 2;
        build(arr, 2 * node, l, mid);
        build(arr, 2 * node + 1, mid + 1, r);
        tree[node] = (tree[2 * node] + tree[2 * node + 1]) % MOD;
    }

    void apply(int node, long long mul, long long add) {
        tree[node] = (tree[node] * mul + add) % MOD;
        if (tree[node] < 0) tree[node] += MOD;
        // Compose lazy tags: existing (lazy_mul[node], lazy_add[node]) with new (mul, add)
        // New lazy: (lazy_mul[node] * mul mod MOD, (lazy_add[node] * mul + add) mod MOD)
        lazy_mul[node] = (lazy_mul[node] * mul) % MOD;
        lazy_add[node] = (lazy_add[node] * mul + add) % MOD;
        if (lazy_add[node] < 0) lazy_add[node] += MOD;
    }

    void push(int node, int l, int r) {
        if (lazy_mul[node] == 1 && lazy_add[node] == 0) return;
        if (l != r) {
            int mid = (l + r) / 2;
            apply(2 * node, lazy_mul[node], lazy_add[node]);
            apply(2 * node + 1, lazy_mul[node], lazy_add[node]);
        }
        lazy_mul[node] = 1;
        lazy_add[node] = 0;
    }

    void update(int node, int l, int r, int ql, int qr, long long mul, long long add) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            apply(node, mul, add);
            return;
        }
        push(node, l, r);
        int mid = (l + r) / 2;
        update(2 * node, l, mid, ql, qr, mul, add);
        update(2 * node + 1, mid + 1, r, ql, qr, mul, add);
        tree[node] = (tree[2 * node] + tree[2 * node + 1]) % MOD;
    }

    long long query(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) {
            return tree[node];
        }
        push(node, l, r);
        int mid = (l + r) / 2;
        long long left_sum = query(2 * node, l, mid, ql, qr);
        long long right_sum = query(2 * node + 1, mid + 1, r, ql, qr);
        return (left_sum + right_sum) % MOD;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<long long> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    SegmentTree st(n);
    st.build(arr, 1, 0, n - 1);

    while (q--) {
        string op;
        cin >> op;
        if (op == "ADD") {
            int l, r;
            long long x;
            cin >> l >> r >> x;
            x = (x % MOD + MOD) % MOD;
            st.update(1, 0, n - 1, l, r, 1, x);
        } else if (op == "MUL") {
            int l, r;
            long long x;
            cin >> l >> r >> x;
            x = (x % MOD + MOD) % MOD;
            st.update(1, 0, n - 1, l, r, x, 0);
        } else if (op == "SUM") {
            int l, r;
            cin >> l >> r;
            cout << st.query(1, 0, n - 1, l, r) << "\n";
        }
    }

    return 0;
}
